+/**
+ * URL validation utilities for security checks
+ */
+
+export function isValidUrl(url: string): boolean {
+  try {
+    const parsed = new URL(url);
+    // Ensure URL parsing succeeded and has valid structure
+    return parsed.protocol && parsed.hostname;
+  } catch (e) {
+    return false;
+  }
+}
+
+export function isFirebaseDomain(url: string): boolean {
+  try {
+    const parsed = new URL(url);
+    const hostname = parsed.hostname;
+    
+    // Allow Firebase domains and subdomains
+    const firebaseDomains = [
+      'firebaseapp.com',
+      'firebase.googleapis.com',
+      'firebasestorage.googleapis.com'
+    ];
+    
+    return firebaseDomains.some(domain => hostname.endsWith(domain));
+  } catch (e) {
+    return false;
+  }
+}

