From: Security Engineer <security@example.com>
Date: [Current Date]
Subject: [PATCH] Fix XSS vulnerability in HTML content rendering

---
 packages/lib/Note.js | 12 +++++++++++-
 1 file changed, 11 insertions(+), 1 deletion(-)

diff --git a/packages/lib/Note.js b/packages/lib/Note.js
index a1b2c3d4e..f5e6a7b8c 100644
--- a/packages/lib/Note.js
+++ b/packages/lib/Note.js
@@ -1,6 +1,7 @@
 const BaseModel = require('./BaseModel').default;
 const { Database } = require('./database');
 const { _ } = require('./locale');
+const { escapeHtml } = require('./htmlUtils');

 class Note extends BaseModel {
 	static tableName() {
@@ -123,7 +124,16 @@ class Note extends BaseModel {
 	}

 	static renderBody(body) {
-		return body;
+		// Escape HTML entities to prevent XSS when rendering user content
+		// in HTML contexts. This ensures user-controlled data is safely
+		// displayed without executing scripts.
+		if (typeof body !== 'string') return body;
+		
+		// Only escape if the content appears to contain HTML tags
+		// to preserve plain text formatting while preventing XSS
+		if (/<[^>]*>/.test(body)) {
+			return escapeHtml(body);
+		}
+		return body;
 	}
 }

