+/**
+ * Escapes a string for safe embedding in JavaScript/TypeScript code
+ * Handles special characters, escape sequences, and prevents code injection
+ */
+function escapeForJsString(str: string): string {
+  if (!str) return str;
+  
+  return str
+    .replace(/\\/g, '\\\\')     // Escape backslashes first
+    .replace(/"/g, '\\"')       // Escape double quotes
+    .replace(/'/g, "\\'")       // Escape single quotes
+    .replace(/\n/g, '\\n')      // Escape newlines
+    .replace(/\r/g, '\\r')      // Escape carriage returns
+    .replace(/\t/g, '\\t')      // Escape tabs
+    .replace(/\f/g, '\\f')      // Escape form feeds
+    .replace(/\b/g, '\\b')      // Escape backspaces
+    .replace(/\v/g, '\\v')      // Escape vertical tabs
+    .replace(/\0/g, '\\0')      // Escape null characters
+    .replace(/\$/g, '\\$')      // Escape $ to prevent template injection
