+    let stderr = '';
+
+    child.stdout.on('data', (data) => (stdout += data.toString()));
+    child.stderr.on('data', (data) => (stderr += data.toString()));
+
+    child.on('close', (code) => {
+      code === 0 ? resolve(stdout) : reject(new Error(stderr || `Process exited with code ${code}`));
+    });
+  });
+}

