+/**
+ * Validates push notification payloads to prevent crashes from invalid input
+ */
+
+function validatePushPayload(deviceTokens, payload, platform) {
+  // Validate device tokens
+  if (!Array.isArray(deviceTokens)) {
+    return new Error('Device tokens must be an array');
+  }
+
+  if (deviceTokens.length === 0) {
+    return new Error('Device tokens array cannot be empty');
+  }
+
+  for (let i = 0; i < deviceTokens.length; i++) {
+    const token = deviceTokens[i];
+    if (typeof token !== 'string' || token.trim().length === 0) {
+      return new Error(`Invalid device token at index ${i}: must be a non-empty string`);
+    }
+  }
+
+  // Validate payload structure
+  if (!payload || typeof payload !== 'object') {
+    return new Error('Payload must be an object');
+  }
+
+  // Validate notification object if present
+  if (payload.notification) {
+    if (typeof payload.notification !== 'object') {
+      return new Error('Notification must be an object');
+    }
+
+    // Validate title and body if provided
+    if (payload.notification.title !== undefined && 
+        typeof payload.notification.title !== 'string') {
+      return new Error('Notification title must be a string');
+    }
+
+    if (payload.notification.body !== undefined && 
+        typeof payload.notification.body !== 'string') {
+      return new Error('Notification body must be a string');
+    }
+  }
+
+  // Platform-specific validations
+  if (platform === 'apns' && payload.badge !== undefined) {
+    if (typeof payload.badge !== 'number' || payload.badge < 0 || !Number.isInteger(payload.badge)) {
+      return new Error('APNS badge must be a non-negative integer');
+    }
+  }
+
+  return null;
+}
+
+module.exports = { validatePushPayload };
+

