+import { Context } from "./context";
+
+/**
+ * Safely evaluate JavaScript expressions without allowing arbitrary code execution.
+ * Replaces the unsafe eval() function with a sandboxed alternative.
+ */
+export function safeEval(expression: string, context: Context): any {
+    // Whitelist of allowed operations and patterns
+    const ALLOWED_PATTERNS = [
+        // Basic arithmetic and comparisons
+        /^[0-9\s+\-*\/%().><=!&|^~]+$/,
+        // Property access on allowed objects
+        /^[a-zA-Z_$][a-zA-Z0-9_$]*(\.[a-zA-Z_$][a-zA-Z0-9_$]*)*$/,
+        // Array indexing
+        /^[a-zA-Z_$][a-zA-Z0-9_$]*(\[[0-9]+\])+$/,
+        // Function calls on whitelisted functions only
+        /^[a-zA-Z_$][a-zA-Z0-9_$]*\([^)]*\)$/
+    ];
+    
+    // Check if expression matches any allowed pattern
+    const isAllowed = ALLOWED_PATTERNS.some(pattern => pattern.test(expression.trim()));
+    
+    if (!isAllowed) {
+        throw new Error(`Disallowed expression: ${expression}`);
+    }
+    
+    // Create a sandboxed context with only allowed properties
+    const sandbox: Record<string, any> = {
+        // Basic JavaScript objects (read-only)
+        Math: Object.freeze({
+            abs: Math.abs,
+            ceil: Math.ceil,
+            floor: Math.floor,
+            max: Math.max,
+            min: Math.min,
+            round: Math.round,
+            sqrt: Math.sqrt,
+            pow: Math.pow,
+            random: Math.random
+        }),
+        Date: Date,
+        Number: Number,
+        String: String,
+        Boolean: Boolean,
+        Array: Array,
+        Object: Object,
+        JSON: JSON,
+        
+        // Dataview context variables
+        ...context
+    };
+    
+    // Prevent access to dangerous globals
+    const prohibited = ['eval', 'Function', 'setTimeout', 'setInterval', 'exec', 'execScript'];
+    prohibited.forEach(name => {
+        Object.defineProperty(sandbox, name, {
+            get: () => { throw new Error(`Access to ${name} is prohibited`); }
+        });
+    });
+    
+    // Use Function constructor in strict mode to create isolated execution
+    const fn = new Function('sandbox', `
+        "use strict";
+        with (sandbox) { return (${expression}); }
+    `);
+    return fn(sandbox);
+}
