+/**
+ * Validates Content-Type header to prevent code injection attacks
+ * @param contentType The Content-Type header value
+ * @throws BadRequestException if Content-Type contains potentially dangerous content
+ */
+export function validateContentType(contentType: string): void {
+  if (!contentType) {
+    return;
+  }
+
+  // Check for dangerous patterns that could lead to code injection
+  const dangerousPatterns = [
+    /eval\s*\(/i,
+    /new\s+Function/i,
+    /setTimeout\s*\([^)]*\)/i,
+    /setInterval\s*\([^)]*\)/i,
+    /script/i,
+    /javascript:/i,
+    /data:/i,
+    /vbscript:/i,
+    /expression\s*\(/i,
+    /on\w+\s*=/i,
+  ];
+
+  for (const pattern of dangerousPatterns) {
+    if (pattern.test(contentType)) {
+      throw new Error(`Invalid Content-Type header: potentially dangerous content detected`);
+    }
+  }
+}
